#include <Arduino.h>
SemaphoreHandle_t mutex = nullptr;
int sharedValue = 0;
void writer(void*) { for (;;) { if (xSemaphoreTake(mutex, pdMS_TO_TICKS(100)) == pdTRUE) { ++sharedValue; xSemaphoreGive(mutex); } vTaskDelay(pdMS_TO_TICKS(250)); } }
void setup() { Serial.begin(115200); mutex = xSemaphoreCreateMutex(); if (mutex) xTaskCreate(writer, "writer", 2048, nullptr, 1, nullptr); }
void loop() { int snapshot; if (mutex && xSemaphoreTake(mutex, pdMS_TO_TICKS(50)) == pdTRUE) { snapshot = sharedValue; xSemaphoreGive(mutex); Serial.println(snapshot); } vTaskDelay(pdMS_TO_TICKS(1000)); }

